ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn="everywhere"
fun buildPartyName(customer) =
  customer.firstName ++ " " ++ customer.lastName


fun buildPartyAddress(address, countryCode) = {
  addressLine1:         address.street,
  addressCityName:      address.city,
  addressStateProvince: address.state,
  addressPostalCode:    address.zip,
  addressCountryCode:   countryCode
}


fun buildInvolvementAddress(addr) = {
  addressLine1:         addr.addressLine,
  addressCityName:      addr.city,
  addressStateProvince: addr.state,
  addressPostalCode:    addr.postalCode,
  addressCountryCode:   addr.country
}


fun buildUSCitizenIdentification(citizenship) = {
  partyLegalStatus: "us_citizen",
  partyIdentificationRecord: {
    partyIdentificationType:  "SSN",
    partyIdentificationValue: citizenship.ssnOrItin
  }
}


fun buildNonUSIdentification(citizenship) = {
  partyLegalStatus: "non_us",
  partyIdentificationRecord: {
    partyIdentificationType:          "PASSPORT",
    partyIdentificationValue:         citizenship.passport.number,
    partyIdentificationIssueDate:     citizenship.passport.issuanceDate,
    partyIdentificationExpiryDate:    citizenship.passport.expirationDate,
    partyIdentificationIssuingCountry: citizenship.passport.country
  },

  partyTaxIdentificationRecord:
    if (citizenship.ssnOrItin == null) null
    else {
      partyIdentificationType:  "SSN",
      partyIdentificationValue: citizenship.ssnOrItin
    },
  partyVisaRecord: {
    partyVisaType:       citizenship.visa."type",
    partyVisaNumber:     citizenship.visa.number,
    partyVisaIssueDate:  citizenship.visa.issueDate,
    partyVisaExpiryDate: citizenship.visa.expiryDate
  },

  otherPartyIdentificationRecords:
    citizenship.otherGovernmentIds map (id) -> {
      partyIdentificationType:  id.idType,
      partyIdentificationValue: id.idValue
    }
}


fun buildPartyInvolvement(profiles) =
  profiles map (profile) ->
    if (profile.profileType == "student")

      {
        partyInvolvementType: "EDUCATION",
        partyInvolvementRecord: {
          institutionName:              profile.universityName,
          institutionStudentReference:  profile.studentId,
          studentVisaDocumentReference: profile.i20Number default null,
          partyInvolvementEndDate:      profile.expectedGraduation,
          partyInvolvementAddress:
            profile.addresses map (addr) -> buildInvolvementAddress(addr)
        }
      }
    else

      {
        partyInvolvementType: "EMPLOYMENT",
        partyInvolvementRecord: {
          institutionName:                 profile.organizationName,
          employmentVisaDocumentReference: profile.h1bOrEadNumber default null,
          partyInvolvementStartDate:       profile.employmentStart,
          partyInvolvementAddress:
            profile.addresses map (addr) -> buildInvolvementAddress(addr)
        }
      }


---
{

  onboardingCaseReference: payload.caseId,


  partyRecord: {
    partyName:        buildPartyName(payload.customer),
    partyDateOfBirth: payload.customer.dateOfBirth,
    partyNationality: payload.customer.country,
    partyContactDetails: {
      partyContactEmailAddress: payload.customer.email default null,
      partyContactPhone:        payload.customer.phone default null
    },
    partyAddress: buildPartyAddress(payload.customer.address, payload.customer.country)
  },


  partyIdentification:
    if (payload.citizenship.status == "us_citizen")
      buildUSCitizenIdentification(payload.citizenship)
    else
      buildNonUSIdentification(payload.citizenship),


  partyInvolvement: buildPartyInvolvement(payload.additionalProfiles)
}
